#' Look up an unexported RosettaCOTS function by name
#'
#' RosettaCOTS exports only [RosettaCOTS::COTS_calibrate()] -- its ~30
#' per-model `pred*From*()` functions (one per D-02 pairwise calibration,
#' each reading its own bundled posterior from
#' `system.file("extdata", ..., package = "RosettaCOTS")`) are internal.
#' RosettaGBR's own `predMantaFromCull()`/`predCullFromManta()`/etc.
#' (`R/wrappers_d02.R`, generated by `data-raw/generate_d02_wrappers.R`) are
#' thin, signature-preserving re-exports of those internals, obtained via
#' this helper rather than `RosettaCOTS:::fn` so the forwarding is a single,
#' auditable call site.
#'
#' @param name Name of the internal RosettaCOTS function.
#' @return The function itself.
#' @keywords internal
#' @noRd
rosettacots_fn <- function(name) {
  if (!requireNamespace("RosettaCOTS", quietly = TRUE)) {
    stop(
      "The '", name, "' D-02 model wrapper requires the 'RosettaCOTS' package ",
      "(https://github.com/Scott-Foster/RosettaCOTS), which is not installed.",
      call. = FALSE
    )
  }
  utils::getFromNamespace(name, "RosettaCOTS")
}
